mapper.select:
SELECT cr.CR_NO AS crNo, cr.DRAWING_NO AS drawingNo, cr.REV_NO AS revNo, cr.CR_TITLE_NM AS crTitleNm, cr.CR_TYPE_CD AS crTypeCd, FN_GET_CD_NM('crTypeCd', cr.CR_TYPE_CD, #{sessionLang}) AS crTypeDesc, cr.PURCHASER_UID AS purchaserUid, purchaser.USER_NM AS purchaserUserNm, req.INSERT_DT AS requestDt, req.APPROVAL_DT AS approvalDt, req.STATUS_CD AS statusCd, cr.STATUS_CD AS crStatusCd, FN_GET_CD_NM('crRequestStatusCd', req.STATUS_CD, #{sessionLang}) AS statusNm, FN_GET_CD_NM('crStatusCd', cr.STATUS_CD, #{sessionLang}) AS crStatusNm, cr.BUSINESS_AREA_CD AS businessAreaCd, FN_GET_CD_NM('businessAreaCd', cr.BUSINESS_AREA_CD, #{sessionLang}) AS businessAreaNm, COALESCE(cr.PRODUCT_NO, '') AS productNm, cr.PRODUCT_NO AS productNo, (SELECT COMPANY_NM FROM DOCS_COMPANY company WHERE company.BIZ_NO = cr.VENDOR_NO) AS vendorNm, cr.VENDOR_NO AS vendorNo, (SELECT USER_NM FROM DOCS_USER vendor WHERE vendor.USER_ID = cr.VENDOR_UID) AS vendorUserNm, cr.VENDOR_UID AS vendorUid FROM ITN_CR cr JOIN DOCS_REQUEST_MAPPING reqMapping ON reqMapping.OBJECT_ID = cr.CR_NO AND reqMapping.USE_YN = 'Y' JOIN DOCS_REQUEST req ON req.REQUEST_NO = reqMapping.REQUEST_NO JOIN DOCS_USER purchaser ON purchaser.USER_ID = cr.PURCHASER_UID JOIN DOCS_REQUEST_DETAIL currDetail ON currDetail.REQUEST_NO = req.REQUEST_NO AND currDetail.PROCESS_SEQ = req.CURRENT_PROCESS_SEQ_NO WHERE cr.STATUS_CD = 20 AND req.REQUEST_TYPE = 'CR' AND req.STATUS_CD = 'REQUEST' AND req.CURRENT_PROCESS_SEQ_NO = 3 AND currDetail.APPROVAL_STATUS_CD = 'ACCEPT' AND currDetail.ACTUAL_USER_CD = #{sessionUser.userCd} AND currDetail.ACTION_CD = 'REQUEST'
AND req.INSERT_DT BETWEEN #{requestStartDt}::DATE AND (#{requestEndDt}::DATE + INTERVAL '1 DAY')
AND cr.VENDOR_NO = #{vendorNo}
AND cr.PURCHASER_UID = #{purchaserUid}
AND cr.STATUS_CD = #{crStatusCd}
AND cr.BUSINESS_AREA_CD = #{businessAreaCd}
ORDER BY req.INSERT_DT DESC, cr.CR_NO DESC
ORDER BY ${sortColumn} ${order}, cr.CR_NO ${order}
LIMIT #{end} OFFSET #{start}

SELECT COUNT(*) FROM ITN_CR cr JOIN DOCS_REQUEST_MAPPING reqMapping ON reqMapping.OBJECT_ID = cr.CR_NO AND reqMapping.USE_YN = 'Y' JOIN DOCS_REQUEST req ON req.REQUEST_NO = reqMapping.REQUEST_NO JOIN DOCS_USER purchaser ON purchaser.USER_ID = cr.PURCHASER_UID JOIN DOCS_REQUEST_DETAIL currDetail ON currDetail.REQUEST_NO = req.REQUEST_NO AND currDetail.PROCESS_SEQ = req.CURRENT_PROCESS_SEQ_NO WHERE cr.STATUS_CD = 20 AND req.REQUEST_TYPE = 'CR' AND req.STATUS_CD = 'REQUEST' AND req.CURRENT_PROCESS_SEQ_NO = 3 AND currDetail.APPROVAL_STATUS_CD = 'ACCEPT' AND currDetail.ACTUAL_USER_CD = #{sessionUser.userCd} AND currDetail.ACTION_CD = 'REQUEST'
AND req.INSERT_DT BETWEEN #{requestStartDt}::DATE AND (#{requestEndDt}::DATE + INTERVAL '1 DAY')
AND cr.VENDOR_NO = #{vendorNo}
AND cr.PURCHASER_UID = #{purchaserUid}
AND cr.STATUS_CD = #{crStatusCd}
AND cr.BUSINESS_AREA_CD = #{businessAreaCd}

mapper.update:
UPDATE ITN_CR cr
   SET STATUS_CD = #{statusCd}


	   , REVIEW_RESULT = #{reviewResult}
	   , PRODUCT_NO = #{productNo}

	   , MATERIAL_NO = #{materialNo}



	   , REJECT_REASON = #{rejectReason}


 WHERE cr.CR_NO = #{crNo}
   AND cr.STATUS_CD = 20
   AND EXISTS (
	SELECT 1
	  FROM DOCS_REQUEST_MAPPING reqMapping
	  JOIN DOCS_REQUEST request
		ON request.REQUEST_NO = reqMapping.REQUEST_NO
	 WHERE reqMapping.OBJECT_ID = cr.CR_NO
	   AND reqMapping.USE_YN = 'Y'
	   AND request.REQUEST_TYPE = 'CR'
	   AND request.STATUS_CD = #{actionCd}
	   AND request.CURRENT_PROCESS_SEQ_NO = #{currentProcessSeqNo}
	   AND EXISTS (
		SELECT 1
		  FROM DOCS_REQUEST_DETAIL completedDetail
		 WHERE completedDetail.REQUEST_NO = request.REQUEST_NO
		   AND completedDetail.PROCESS_SEQ = 3
		   AND completedDetail.APPROVAL_STATUS_CD = 'ACCEPT'
		   AND completedDetail.ACTUAL_USER_CD = #{sessionUser.userCd}
		   AND completedDetail.ACTION_CD = #{actionCd}
	   )
   )
